// Type declarations for Nuxt auto-imports and internal path aliases
// that vue-tsc cannot resolve without the full Nuxt type generation.

declare module '#i18n' {
  export function useLocalePath(): (path: string) => string
  export function useI18n(): any
}

declare module '../composables/useAuth' {
  export function useAuth(): any
}

declare module '~/lib/auth-client' {
  export const authClient: any
}

declare module '../../lib/auth-client' {
  export const authClient: any
}

declare module '../../../lib/auth-client' {
  export const authClient: any
}

declare module '../../../../lib/auth-client' {
  export const authClient: any
}

declare module '../../../../../lib/auth-client' {
  export const authClient: any
}

declare module '#auth/lib/auth-client' {
  export const authClient: any
}

// Generated by modules/auth-plugins.ts from the registered
// packages/plugins/Authentication/auth-* packages.
declare module '#auth-server-plugins' {
  const factories: Array<(context: import('./server/utils/auth').AuthPluginContext) => import('better-auth').BetterAuthPlugin | import('better-auth').BetterAuthPlugin[]>
  export default factories
}

declare module '#auth-client-plugins' {
  const factories: Array<() => import('better-auth/client').BetterAuthClientPlugin | import('better-auth/client').BetterAuthClientPlugin[]>
  export default factories
}

// Generated by modules/auth-plugins.ts: every auth plugin package (trusted
// ones in `#auth-server-plugins` order), with sandboxed plugins' manifests
// and sources.
declare module '#auth-plugin-registry' {
  const registry: import('./server/utils/plugins/host').AuthPluginRegistry
  export default registry
}
